Method.Source:
/// <summary>
/// The active method of the form
/// </summary>
/// <param name="sender">Form datasource</param>
/// <param name="e">args</param>
[FormDataSourceEventHandler(formDataSourceStr(ReqItemTable, METReqItemTable), FormDataSourceEventType::Activated),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void METReqItemTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{   
    sender.object(fieldNum(METReqItemTable, Planner)).enabled(NoYes::No);    
}

/// <summary>
/// ReqItemTable_OnWritten
/// </summary>
/// <param name="sender">Form Data Source</param>
/// <param name="e">Form data source event</param>
[FormDataSourceEventHandler(formDataSourceStr(ReqItemTable, ReqItemTable), FormDataSourceEventType::Written),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void ReqItemTable_OnWritten(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun         fr                  = sender.formRun();
    ReqItemTable    reqItemTable        = sender.cursor();
    METReqItemTable metReqItemTable     = fr.dataHelper().FindDataSource(formDataSourceStr(ReqItemTable, METReqItemTable)).cursor();
    metReqItemTable.RefRecId = reqItemTable.RecId;
    FormDataUtil::getFormDataSource(metReqItemTable).write();
}
